package local.velo.bridge;
import org.json.*;import java.util.*;
public final class RouteCodec {
 public static String encode(RouteModel r)throws Exception{JSONObject o=new JSONObject().put("name",r.name).put("road",r.roadInstructions).put("seconds",r.plannedSeconds);JSONArray p=new JSONArray(),m=new JSONArray();for(int i=0;i<r.x.length;i++){double[] ll=MapMath.point(r,r.x[i],r.y[i]);p.put(new JSONArray().put(ll[0]).put(ll[1]));}for(RouteModel.Maneuver a:r.maneuvers)m.put(new JSONObject().put("s",a.progress).put("d",String.valueOf(a.direction)).put("text",a.text).put("exit",a.exit));return o.put("points",p).put("turns",m).toString();}
 public static RouteModel decode(String raw)throws Exception{JSONObject o=new JSONObject(raw);JSONArray p=o.getJSONArray("points");if(p.length()>12000)throw new IllegalArgumentException("路线过大");ArrayList<double[]> pts=new ArrayList<>();for(int i=0;i<p.length();i++)pts.add(new double[]{p.getJSONArray(i).getDouble(0),p.getJSONArray(i).getDouble(1)});RouteModel r=new RouteModel(o.getString("name"),pts,o.optBoolean("road"));r.plannedSeconds=o.optDouble("seconds",0);JSONArray m=o.optJSONArray("turns");ArrayList<RouteModel.Maneuver> turns=new ArrayList<>();if(m!=null)for(int i=0;i<m.length();i++){JSONObject a=m.getJSONObject(i);double s=a.getDouble("s");String d=a.getString("d");if(!Double.isFinite(s)||s<0||s>r.length+20||d.length()!=1||"SLRUONA".indexOf(d.charAt(0))<0)throw new IllegalArgumentException("转向数据无效");turns.add(new RouteModel.Maneuver(s,d.charAt(0),a.optString("text"),a.optInt("exit")));}r.maneuvers=turns;return r;}
 public static RouteModel combine(List<RouteModel> legs,String name)throws Exception{ArrayList<double[]> points=new ArrayList<>();for(RouteModel r:legs)for(int i=0;i<r.x.length;i++)points.add(MapMath.point(r,r.x[i],r.y[i]));if(points.size()>12000)throw new IllegalArgumentException("路线过长，请减少途经点");RouteModel result=new RouteModel(name,points,true);ArrayList<RouteModel.Maneuver> turns=new ArrayList<>();double last=0;for(RouteModel r:legs){result.plannedSeconds+=r.plannedSeconds;for(RouteModel.Maneuver m:r.maneuvers){double[] ll=MapMath.point(r,r.at(m.progress).x,r.at(m.progress).y);double s=result.progressAt(ll[0],ll[1],last);last=s;turns.add(new RouteModel.Maneuver(s,m.direction,m.text,m.exit));}}result.maneuvers=turns;return result;}
}
